    rye_flour: () => K.sack(C.greyL, ear(C.creamD, C.greyD, { w: 3.6, awns: C.greyD, rot: -14, stem: C.greyD }) + ear(C.creamD, C.greyD, { w: 3.6, awns: C.greyD, rot: 14, stem: C.greyD }) + mound(C.greyL)),
