      const p = (rr, t) => `${(cx + rr * Math.cos(t)).toFixed(1)} ${(cy + rr * Math.sin(t)).toFixed(1)}`;
      rays += `M${p(r + 2, a - b)} L${p(r + ray, a)} L${p(r + 2, a + b)} Z `;
