        K.hi(`M${x - len + 4} ${y - 5} H${x + len - 4} V${y - 3} H${x - len + 4} Z`) + `</g>`;
      return K.shadow(26) + cannolo(30, 28, -14, 20) + cannolo(34, 44, -14, 20);
