        `<path d="M32 18 L20 13 L27 12.5 L24 7 L32 11 L40 7 L37 12.5 L44 13 Z" fill="${C.leaf}" stroke-width="1.8"/>` +
        stem('M32 10 C32 7 33 5 35 3', C.leafD, 2.5);
