  const Ci = (cx, cy, r, fill, sw = '') => `<circle cx="${cx}" cy="${cy}" r="${r}" fill="${fill}"${sw ? ` stroke-width="${sw}"` : ''}/>`;
  const at = (x, y, rot, m) => `<g transform="translate(${x} ${y}) rotate(${rot})">${m}</g>`;
  // A scatter of grains (rx, ry) at given points: [[x, y, rot], ...].
