    let m = `<path d="M0 ${-t} C${len * 0.45} ${-t} ${len * 0.8} ${-t * 0.35} ${len} 0 L${len + tail} 0.5 L${len} 1 C${len * 0.8} ${t * 0.4} ${len * 0.45} ${t} 0 ${t} C${cut ? -t * 0.35 : -t * 0.7} ${t} ${cut ? -t * 0.35 : -t * 0.7} ${-t} 0 ${-t} Z" fill="${fill}"/>`;
    let r = '';
